# Code generated by Claude
"""G0 (a), (b), (f): the pedestal's travel limits, the highest and lowest grasp-point height a stance can serve at each pedestal height, and what the bench removes from the maps by height.

    MUJOCO_GL=egl python experiments/g0_reach_band.py [--out docs/reports/g0_reach_band.json]

(a) the pedestal joint's range and the lowest/highest command, from the compiled model.
(b) For each pedestal command in 1 cm steps over the travel: a beaker-sized object (the test scene's beaker at its xy, 14 cm from the bench edge) is put on a support at each height from 0.70 to 1.60 m in
    1 cm steps; its grasp point is the band's middle (the object's height times grasp_height_frac above the support). The region of src/bench_stance.py (all path points of a bench-approach bin: band
    heights, standoff, over, lift; the framing, silhouette and zombie-clearance-to-the-object filters) and the overlay's furniture and home-clearance masks decide whether some floor spot serves it.
    Per pedestal height: the lowest and the highest grasp-point height (above the floor) served, and the maximum and minimum over all pedestal heights.
(f) With the 2-map pilot built without the bench (data/reach_map_nobench_pilot) and the current maps (left bins 0 and 9): per height above the bench top (1 cm steps) the voxels the bench removes, and the
    height above which it removes none.
"""
import argparse
import json
import math
import time

import mujoco
import numpy as np

from experiments.bench_stance_validate import scene_objects
from src import bench_stance as bs
from src import robot_specs
from src.furniture_map import FurnitureMap
from src.home_clearance_map import HomeClearanceMap
from src.stance_checks import StanceChecks
from src.stance_finder import robot_geometry
from src.task_beaker_hotplate import bench_top_z, load_task
from src.task_config import BEAKER_CFG, BENCH_STANCE_CFG, PICK_PLACE_CFG, STANCE_REQUIREMENTS, TASK_CFG

if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default="docs/reports/g0_reach_band.json")
    ap.add_argument("--step", type=float, default=0.01)
    a = ap.parse_args()
    sim = load_task()
    m, d = sim.model, sim.data
    rg = robot_geometry(m)
    out = {}
    # (a)
    jr = [m.jnt_range[m.joint(jn).id].tolist() for jn in robot_specs.PEDESTAL_SPECS["joints"]]
    out["a"] = {"joint_range_model": jr, "spec_range": list(robot_specs.PEDESTAL_SPECS["range"]), "lowest_command": robot_specs.PEDESTAL_SPECS["lowest_command"]}
    print("(a) pedestal joint range in the model:", jr, "spec range", robot_specs.PEDESTAL_SPECS["range"])
    qmax = float(jr[0][1])
    qs = [round(float(q), 4) for q in np.arange(0.0, qmax + 1e-9, a.step)]
    # (f) first: numpy only
    top = bench_top_z(m)
    q_build = TASK_CFG["pedestal_q"]
    shoulder_z = rg["base_z"] + rg["torso_z0"] + rg["lift_factor"] * q_build + rg["shoulder"]["left"][2]
    per_bin = {}
    for b in (0, 9):
        def load(p):
            z = np.load(p)
            n = int(np.prod(z["shape"]))
            return np.unpackbits(z["reached"])[:n].reshape(tuple(z["shape"])).astype(bool), z["origin"], float(z["voxel"])
        nb, o, v = load(f"data/reach_map_nobench_pilot/left_bin{b}.npz")
        bn, _, _ = load(f"data/reach_map/left_bin{b}.npz")
        lost = nb & ~bn
        iz = np.nonzero(lost.any(axis=(0, 1)))[0]
        z_s = o[2] + (np.arange(lost.shape[2]) + 0.5) * v
        h = z_s + shoulder_z - top                                     # height above the bench top, metres
        cm = np.round(h * 100).astype(int)
        per = {}
        for c in np.unique(cm):
            k = int(lost[:, :, cm == c].sum())
            if k:
                per[int(c)] = k
        per_bin[b] = per
        above = [c for c, k in per.items() if k > 0]
        print(f"(f) left bin {b}: bench removes {int(lost.sum()):,} voxels; heights above the bench top with removed voxels: {min(above)} to {max(above)} cm; the bench removes none above {max(above)} cm")
    out["f"] = {"bench_top": top, "shoulder_z_at_build": shoulder_z, "removed_by_cm_above_bench_top": {str(b): {str(c): k for c, k in per.items()} for b, per in per_bin.items()}}
    # (b)
    chk = StanceChecks(m, d, rg["base_z"])
    yaw = TASK_CFG["staging_yaw"]
    t0 = time.time()
    cams = bs.camera_poses(m, qs, chk=chk, ref_stance=(*TASK_CFG["staging_xy"], yaw), cache_dir=BENCH_STANCE_CFG["cache_dir"])
    print(f"camera poses and silhouettes for {len(qs)} heights: {time.time() - t0:.1f} s")
    maps = bs.load_maps("data/reach_map", sides=("left",))
    furn = FurnitureMap.from_model(m, mujoco.MjData(m), exclude_bodies=("task_beaker",))
    objs = scene_objects(m, d)
    beaker = objs[0]
    hcm = HomeClearanceMap(m, d, chk, np.array(beaker["xy"]), robot_geometry=rg, slack=0.0)
    blocked_fn = bs.make_extra_blocked(furn, rg, yaw, hcm.clear_mask)
    cache = {}

    def blocked(X, Y, qs_):
        key = (X.shape, tuple(qs_))
        if key not in cache:
            cache[key] = blocked_fn(X, Y, qs_)
        return cache[key]
    H, frac = BEAKER_CFG["height"], PICK_PLACE_CFG["grasp_height_frac"]
    lo_b, hi_b = BENCH_STANCE_CFG["approach_bins"], None
    lowest, highest = {q: None for q in qs}, {q: None for q in qs}
    n_ = bs.bench_frame(yaw)[0]
    t0 = time.time()
    for s in np.arange(0.70, 1.60 + 1e-9, 0.01):
        o = dict(beaker)
        band = [s + f * H for f in np.arange(BEAKER_CFG["grasp_band"][0], BEAKER_CFG["grasp_band"][1] + 1e-9, 0.05)]
        o.update(z_points=band, surface_z=s, corners=np.array([[c[0], c[1], s + (c[2] - top)] for c in beaker["corners"]]),
                 samples=np.array([[p[0], p[1], s + (p[2] - top)] for p in beaker["samples"]]), z0=s, z1=s + H)
        try:
            res = bs.overlay([o], maps, rg, cams, {"yaw": yaw, "open": TASK_CFG["bench_open"]}, blocked, use_cache=False, say=lambda *_: None)
        except bs.BenchStanceError:
            continue
        ok_q = np.nonzero(((res["stack"][0] > 0)).any(axis=(1, 2)))[0]
        zg = s + frac * H
        for qi in ok_q:
            q = qs[qi]
            lowest[q] = zg if lowest[q] is None else min(lowest[q], zg)
            highest[q] = zg if highest[q] is None else max(highest[q], zg)
    print(f"(b) sweep of 91 support heights x {len(qs)} pedestal heights: {time.time() - t0:.0f} s")
    print(" q (m) | lowest grasp-point height (m) | highest (m)")
    for q in qs:
        print(f" {q:.2f}  | {'-' if lowest[q] is None else f'{lowest[q]:.3f}':>8}                    | {'-' if highest[q] is None else f'{highest[q]:.3f}':>8}")
    served = [q for q in qs if lowest[q] is not None]
    out["b"] = {"qs": qs, "lowest": [lowest[q] for q in qs], "highest": [highest[q] for q in qs], "min_over_q": min(lowest[q] for q in served), "max_over_q": max(highest[q] for q in served)}
    print(f"(b) minimum over all pedestal heights: {out['b']['min_over_q']:.3f} m; maximum: {out['b']['max_over_q']:.3f} m (bench top {top:.3f} m: the highest support served is {out['b']['max_over_q'] - frac * H - top:+.3f} m above it)")
    json.dump(out, open(a.out + ".tmp", "w"))
    import os
    os.replace(a.out + ".tmp", a.out)
